&lt;h2 data-section-id=&quot;1qaibhf&quot; data-start=&quot;3650&quot; data-end=&quot;3680&quot;&gt;&lt;strong data-start=&quot;3653&quot; data-end=&quot;3680&quot;&gt;Skills &amp;amp; Qualifications&lt;/strong&gt;&lt;/h2&gt;
